import android.content.Context;
import com.zirenmidori.gcg.release.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import java.util.zip.*;
import org.json.*;

public final class UpdaterHostTest {
    static int passed;static KeyPair keys;static File root;
    interface Checked{void run()throws Exception;}
    static void test(String name,Checked body)throws Exception{body.run();passed++;System.out.println("PASS "+name);}
    static void yes(boolean condition,String why){if(!condition)throw new AssertionError(why);}
    static void rejects(Checked action)throws Exception{try{action.run();}catch(IOException expected){return;}throw new AssertionError("Expected integrity/path rejection");}
    static byte[] b(String value){return value.getBytes(StandardCharsets.UTF_8);}
    static String sha(byte[] value)throws Exception{return ReleaseIO.hex(MessageDigest.getInstance("SHA-256").digest(value));}
    static void write(File file,byte[] data)throws Exception{file.getParentFile().mkdirs();Files.write(file.toPath(),data);}
    static byte[] sign(byte[] raw,KeyPair pair)throws Exception{Signature s=Signature.getInstance("SHA256withRSA");s.initSign(pair.getPrivate());s.update(raw);return s.sign();}
    static Context context(String name)throws Exception{File folder=new File(root,name);folder.mkdirs();write(new File(folder,"assets/gcg-release/publickey.der"),keys.getPublic().getEncoded());return new Context(folder);}
    static JSONObject row(String name,byte[] data)throws Exception{return new JSONObject().put("path",name).put("size",data.length).put("sha256",sha(data));}
    static JSONObject doc(String release,String base)throws Exception{return new JSONObject().put("schemaVersion",1).put("kind",base==null?"full":"delta").put("packageName",ReleaseManifest.APP_ID).put("releaseId",release).put("baseReleaseId",base==null?JSONObject.NULL:base).put("minApkVersionCode",10137).put("files",new JSONArray()).put("packs",new JSONArray()).put("remove",new JSONArray()).put("serverPayload",JSONObject.NULL).put("apk",JSONObject.NULL);}
    static ReleaseManifest manifest(Context c,JSONObject doc)throws Exception{byte[] raw=b(doc.toString());return ReleaseManifest.verify(c,raw,sign(raw,keys));}
    static void state(Context c,String release)throws Exception{ReleaseStore.writeJson(new File(ReleaseStore.root(c),"committed.json"),new JSONObject().put("schemaVersion",1).put("releaseId",release).put("manifestSha256",sha(b(release))));}
    static void zip(File file,Map<String,byte[]> members)throws Exception{file.getParentFile().mkdirs();try(ZipOutputStream z=new ZipOutputStream(new FileOutputStream(file))){for(Map.Entry<String,byte[]> e:members.entrySet()){z.putNextEntry(new ZipEntry(e.getKey()));z.write(e.getValue());z.closeEntry();}}}
    static File update(Context c,String name,JSONObject doc,Map<String,byte[]> contents,KeyPair signer,boolean includePublisher)throws Exception{Map<String,byte[]> entries=new LinkedHashMap<>(contents);byte[] raw=b(doc.toString());entries.put("manifest.json",raw);entries.put("manifest.sig",sign(raw,signer));if(includePublisher)entries.put("publisher.der",signer.getPublic().getEncoded());File f=new File(ReleaseStore.root(c),name);zip(f,entries);return f;}
    static File external(Context c,String name)throws Exception{return ReleaseIO.child(ReleaseStore.external(c),name);}
    static String text(File f)throws Exception{return new String(Files.readAllBytes(f.toPath()),StandardCharsets.UTF_8);}
    public static void main(String[] args)throws Exception{
        root=new File(args[0]).getCanonicalFile();root.mkdirs();KeyPairGenerator generator=KeyPairGenerator.getInstance("RSA");generator.initialize(2048);keys=generator.generateKeyPair();
        test("publisher signature and tamper rejected",()->{Context c=context("signature");JSONObject d=doc("0.1.1","0.1.0");byte[] raw=b(d.toString()),sig=sign(raw,keys);ReleaseManifest.verify(c,raw,sig);raw[raw.length-2]^=1;rejects(()->ReleaseManifest.verify(c,raw,sig));});
        test("traversal/private state namespaces rejected",()->{for(String path:Arrays.asList("../state.json","/setting.u","a/../setting.u","a\\b.u","gcg-server/data/state.json","Unity/Analytics/x.u","updates/x.u","a/.hidden.u","GMCmdParams.json"))rejects(()->ReleaseManifest.resource(path));ReleaseManifest.resource("AutoAudio/Android/English(US)/Vo_Normal_Girl_27.bnk");});
        test("negative and fractional manifest sizes rejected",()->{Context c=context("numbers");for(Object n:Arrays.asList(-1,1.5,"4")){JSONObject d=doc("0.1.1","0.1.0");d.getJSONArray("files").put(row("a.u",b("A")).put("size",n));rejects(()->manifest(c,d));}});
        test("complete manual first-install data is adopted without download or copy",()->{Context c=context("adopt-full");JSONObject d=doc("0.1.0",null);d.getJSONArray("files").put(row("a.u",b("A")).put("pack","one")).put(row("version.data",b("index")).put("pack","one"));d.getJSONArray("packs").put(new JSONObject().put("id","one").put("url","https://127.0.0.1:1/must-not-connect.zip").put("size",1).put("sha256",sha(b("x"))));byte[] raw=b(d.toString());write(new File(root,"adopt-full/assets/gcg-release/manifest.json"),raw);write(new File(root,"adopt-full/assets/gcg-release/manifest.sig"),sign(raw,keys));write(external(c,"a.u"),b("A"));write(external(c,"version.data"),b("index"));ReleaseEngine.bootstrap(c,s->{});yes(ReleaseStore.state(c).getString("releaseId").equals("0.1.0"),"adopted marker");yes(!external(c,".gcg-downloads").exists(),"no network staging");yes(!new File(ReleaseStore.root(c),"journal.json").exists(),"no unnecessary asset transaction");});
        test("partial manual data plus resumed verified stage avoids download",()->{Context c=context("adopt-partial");JSONObject d=doc("0.1.0",null);d.getJSONArray("files").put(row("a.u",b("A")).put("pack","one")).put(row("version.data",b("index")).put("pack","two"));for(String id:Arrays.asList("one","two"))d.getJSONArray("packs").put(new JSONObject().put("id",id).put("url","https://127.0.0.1:1/must-not-connect.zip").put("size",1).put("sha256",sha(b("x"))));byte[] raw=b(d.toString());write(new File(root,"adopt-partial/assets/gcg-release/manifest.json"),raw);write(new File(root,"adopt-partial/assets/gcg-release/manifest.sig"),sign(raw,keys));write(external(c,"a.u"),b("A"));File stage=ReleaseStore.newStage(c);write(new File(stage,"new/version.data"),b("index"));ReleaseStore.writeJson(new File(ReleaseStore.root(c),"bootstrap-stage.json"),new JSONObject().put("id",stage.getName().substring(13)).put("manifestSha256",sha(raw)));ReleaseEngine.bootstrap(c,s->{});yes(text(external(c,"a.u")).equals("A")&&text(external(c,"version.data")).equals("index"),"adoption and resume completed");yes(!stage.exists(),"stage cleaned");});
        test("data commit preserves private profile and unrelated resources",()->{Context c=context("commit");state(c,"0.1.0");write(external(c,"a.u"),b("old"));write(external(c,"unrelated.u"),b("keep"));File profile=new File(c.getFilesDir(),"gcg-server/data/state.json");write(profile,b("private profile bytes"));JSONObject d=doc("0.1.1","0.1.0");d.getJSONArray("files").put(row("a.u",b("new"))).put(row("version.data",b("index-new")));File f=update(c,"ok.gcgupdate",d,new LinkedHashMap<String,byte[]>(){{put("files/a.u",b("new"));put("files/version.data",b("index-new"));}},keys,false);ReleaseEngine.importUpdate(c,f,false,s->{});yes(text(external(c,"a.u")).equals("new"),"updated resource");yes(text(external(c,"unrelated.u")).equals("keep"),"unrelated resource");yes(text(profile).equals("private profile bytes"),"profile preserved");yes(ReleaseStore.state(c).getString("releaseId").equals("0.1.1"),"committed release");yes(!new File(ReleaseStore.root(c),"journal.json").exists(),"journal cleanup");});
        test("bad file SHA cannot publish any update",()->{Context c=context("bad-sha");state(c,"0.1.0");write(external(c,"a.u"),b("old"));JSONObject d=doc("0.1.1","0.1.0");d.getJSONArray("files").put(row("a.u",b("new")));File f=update(c,"bad.gcgupdate",d,Collections.singletonMap("files/a.u",b("BAD")),keys,false);rejects(()->ReleaseEngine.importUpdate(c,f,false,s->{}));yes(text(external(c,"a.u")).equals("old"),"must not publish");yes(ReleaseStore.state(c).getString("releaseId").equals("0.1.0"),"base marker unchanged");});
        test("undeclared ZIP entry cannot escape signed file list",()->{Context c=context("extra");state(c,"0.1.0");JSONObject d=doc("0.1.1","0.1.0");File f=update(c,"extra.gcgupdate",d,Collections.singletonMap("files/hidden.u",b("bad")),keys,false);rejects(()->ReleaseEngine.importUpdate(c,f,false,s->{}));yes(!external(c,"hidden.u").exists(),"hidden file absent");});
        test("wrong base release rejected",()->{Context c=context("base");state(c,"0.1.0");JSONObject d=doc("0.1.2","0.1.1");File f=update(c,"base.gcgupdate",d,Collections.emptyMap(),keys,false);rejects(()->ReleaseEngine.importUpdate(c,f,false,s->{}));});
        test("mid-publication failure restores changed assets and release marker",()->{Context c=context("rollback");state(c,"0.1.0");write(external(c,"a.u"),b("old"));write(external(c,"dir"),b("blocking-file"));JSONObject d=doc("0.1.1","0.1.0");d.getJSONArray("files").put(row("a.u",b("new"))).put(row("dir/block.u",b("blocked")));Map<String,byte[]> files=new LinkedHashMap<>();files.put("files/a.u",b("new"));files.put("files/dir/block.u",b("blocked"));File f=update(c,"rollback.gcgupdate",d,files,keys,false);rejects(()->ReleaseEngine.importUpdate(c,f,false,s->{}));yes(text(external(c,"a.u")).equals("old"),"first published asset restored");yes(ReleaseStore.state(c).getString("releaseId").equals("0.1.0"),"release marker restored");});
        test("startup recovery restores interrupted publication before game launch",()->{Context c=context("recovery");state(c,"0.1.0");JSONObject old=ReleaseStore.state(c);File stage=ReleaseStore.newStage(c);write(new File(stage,"backup/a.u"),b("old"));write(external(c,"a.u"),b("new"));JSONObject before=new JSONObject().put("a.u",new JSONObject().put("present",true).put("size",3).put("sha256",sha(b("old"))));JSONObject j=new JSONObject().put("id",stage.getName().substring(13)).put("status","applying").put("planned",new JSONArray().put("a.u")).put("before",before).put("oldState",old);ReleaseStore.writeJson(new File(ReleaseStore.root(c),"journal.json"),j);ReleaseStore.recover(c);yes(text(external(c,"a.u")).equals("old"),"recovered asset");yes(!stage.exists(),"owned stage removed");});
        test("explicit deletion removes only named resource",()->{Context c=context("delete");state(c,"0.1.0");write(external(c,"a.u"),b("remove"));write(external(c,"b.u"),b("keep"));JSONObject d=doc("0.1.1","0.1.0");d.getJSONArray("remove").put("a.u");File f=update(c,"remove.gcgupdate",d,Collections.emptyMap(),keys,false);ReleaseEngine.importUpdate(c,f,false,s->{});yes(!external(c,"a.u").exists()&&text(external(c,"b.u")).equals("keep"),"delete scope");});
        test("foreign publisher requires trust once and cannot carry APK",()->{Context c=context("foreign");state(c,"0.1.0");KeyPair foreign=generator.generateKeyPair();JSONObject d=doc("mod.1","0.1.0");File f=update(c,"mod.gcgupdate",d,Collections.emptyMap(),foreign,true);rejects(()->ReleaseEngine.inspect(c,f,false));ReleaseEngine.inspect(c,f,true);d.put("apk",new JSONObject());File apk=update(c,"bad-apk.gcgupdate",d,Collections.emptyMap(),foreign,true);rejects(()->ReleaseEngine.inspect(c,apk,true));});
        test("server overlay activates immutable code while preserving save",()->{Context c=context("server");state(c,"0.1.0");File profile=new File(c.getFilesDir(),"gcg-server/data/state.json");write(profile,b("save must survive"));Map<String,byte[]> payload=new LinkedHashMap<>();for(String name:Arrays.asList("bootstrap.mjs","package.json","config/default.json","dist/index.js","node_modules/zod/package.json","resources/map/chapter.txt","LICENSES/test.txt"))payload.put(name,b("safe "+name));File server=new File(ReleaseStore.root(c),"server.zip");zip(server,payload);byte[] body=Files.readAllBytes(server.toPath());long expanded=payload.values().stream().mapToLong(a->a.length).sum();JSONObject d=doc("0.1.1","0.1.0");d.put("serverPayload",new JSONObject().put("entry","server/payload.zip").put("size",body.length).put("sha256",sha(body)).put("expandedSize",expanded).put("entries",payload.size()));File update=update(c,"server.gcgupdate",d,Collections.singletonMap("server/payload.zip",body),keys,false);ReleaseEngine.importUpdate(c,update,false,s->{});yes(text(profile).equals("save must survive"),"server update preserves profile");yes(ReleaseStore.activeServer(c).getName().equals(sha(body)),"content addressed server activation");yes(new File(ReleaseStore.activeServer(c),"LICENSES/test.txt").isFile(),"license retained");});
        test("exact APK copy literal reconstruction and bounds/hash rejection",()->{Context c=context("apk-bytes");File source=new File(ReleaseStore.root(c),"source.apk");write(source,b("ABCDEFGH"));File zip=new File(ReleaseStore.root(c),"delta.zip");zip(zip,Collections.singletonMap("apk/000001.bin",b("!xyz!")));JSONObject spec=new JSONObject().put("sourceSha256",sha(b("ABCDEFGH"))).put("targetSha256",sha(b("ABCxyzFGH"))).put("size",9).put("ops",new JSONArray().put(new JSONObject().put("kind","copy").put("offset",0).put("length",3)).put(new JSONObject().put("kind","literal").put("entry","apk/000001.bin").put("offset",1).put("length",3)).put(new JSONObject().put("kind","copy").put("offset",5).put("length",3)));try(ZipFile z=new ZipFile(zip)){File output=new File(ReleaseStore.root(c),"out.apk");ApkDeltaBytes.reconstruct(source,output,z,spec,s->{});yes(text(output).equals("ABCxyzFGH"),"exact reconstructed bytes");spec.put("targetSha256",sha(b("wrong")));rejects(()->ApkDeltaBytes.reconstruct(source,output,z,spec,s->{}));spec.getJSONArray("ops").getJSONObject(0).put("offset",1000);rejects(()->ApkDeltaBytes.reconstruct(source,output,z,spec,s->{}));}});
        test("ordinary offline restarts avoid reparsing the full bootstrap inventory",()->{Context c=context("warm-restart");state(c,"0.1.0");ReleaseEngine.bootstrap(c,s->{throw new AssertionError("No download or staging during a committed restart");});yes(ReleaseStore.state(c).getString("releaseId").equals("0.1.0"),"committed release retained without opening absent bootstrap manifest");});
        test("large first installation publishes with bounded durable journal writes",()->{Context c=context("large-install");JSONObject d=doc("0.1.0",null);File stage=ReleaseStore.newStage(c);for(int i=0;i<120;i++){String name="part"+i+".u";byte[] value=b("resource "+i);d.getJSONArray("files").put(row(name,value).put("pack","one"));write(new File(stage,"new/"+name),value);}d.getJSONArray("packs").put(new JSONObject().put("id","one").put("url","https://example.com/one.zip").put("size",1).put("sha256",sha(b("x"))));int initial=android.system.Os.journalWrites;ReleaseStore.apply(c,manifest(c,d),stage,null);yes(android.system.Os.journalWrites-initial<10,"journal I/O must remain bounded independently of inventory size");for(int i=0;i<120;i++)yes(text(external(c,"part"+i+".u")).equals("resource "+i),"published resource "+i);});
        test("complete rollback plan restores unpublished entries as well as published ones",()->{Context c=context("complete-plan-recovery");state(c,"0.1.0");File stage=ReleaseStore.newStage(c);JSONObject before=new JSONObject();JSONArray planned=new JSONArray();for(String name:Arrays.asList("a.u","b.u")){byte[] old=b("old-"+name);write(new File(stage,"backup/"+name),old);write(external(c,name),name.equals("a.u")?b("published-new"):old);before.put(name,new JSONObject().put("present",true).put("size",old.length).put("sha256",sha(old)));planned.put(name);}before.put("c.u",new JSONObject().put("present",false));planned.put("c.u");ReleaseStore.writeJson(new File(ReleaseStore.root(c),"journal.json"),new JSONObject().put("id",stage.getName().substring(13)).put("status","prepared").put("planned",planned).put("before",before).put("oldState",ReleaseStore.state(c)));ReleaseStore.recover(c);yes(text(external(c,"a.u")).equals("old-a.u")&&text(external(c,"b.u")).equals("old-b.u")&&!external(c,"c.u").exists(),"entire pre-transaction state recovered");});
        test("postponing initial download opens no network connection and preserves staging",()->{Context c=context("download-consent");JSONObject d=doc("0.1.0",null);d.getJSONArray("files").put(row("a.u",b("A")).put("pack","one"));d.getJSONArray("packs").put(new JSONObject().put("id","one").put("url","https://127.0.0.1:1/must-not-connect.zip").put("size",10).put("sha256",sha(b("x"))));byte[] raw=b(d.toString());write(new File(root,"download-consent/assets/gcg-release/manifest.json"),raw);write(new File(root,"download-consent/assets/gcg-release/manifest.sig"),sign(raw,keys));int[] prompts={0};rejects(()->ReleaseEngine.bootstrap(c,new ReleaseDownload.DetailedProgress(){public void show(String s){}public void bytes(long complete,long total){}public void confirmInitialDownload(long total,long expanded)throws IOException{yes(total==10&&expanded==1,"signed download and expansion sizes");prompts[0]++;throw new IOException("Not now");}}));yes(prompts[0]==1&&ReleaseStore.state(c)==null&&!external(c,"a.u").exists(),"consent cancellation prevents publication");yes(new File(ReleaseStore.root(c),"bootstrap-stage.json").isFile(),"retry pointer kept");});
        test("verified resumed packs report cumulative overall progress without redownloading",()->{Context c=context("overall-progress");JSONObject d=doc("0.1.0",null);File stage=ReleaseStore.newStage(c);String[] names={"a.u","version.data"};long total=0;for(int i=0;i<2;i++){byte[] value=b("content"+i);String pack="pack"+i;d.getJSONArray("files").put(row(names[i],value).put("pack",pack));d.getJSONArray("packs").put(new JSONObject().put("id",pack).put("url","https://127.0.0.1:1/must-not-connect.zip").put("size",10+i).put("sha256",sha(b("x"))));write(new File(stage,"new/"+names[i]),value);total+=10+i;}byte[] raw=b(d.toString());write(new File(root,"overall-progress/assets/gcg-release/manifest.json"),raw);write(new File(root,"overall-progress/assets/gcg-release/manifest.sig"),sign(raw,keys));ReleaseStore.writeJson(new File(ReleaseStore.root(c),"bootstrap-stage.json"),new JSONObject().put("id",stage.getName().substring(13)).put("manifestSha256",sha(raw)));List<Long> reports=new ArrayList<>();ReleaseEngine.bootstrap(c,new ReleaseDownload.DetailedProgress(){public void show(String s){}public void bytes(long complete,long total){yes(total==21,"overall denominator");reports.add(complete);}public void confirmInitialDownload(long total,long expanded){throw new AssertionError("No download needed for complete verified stage");}});yes(reports.equals(Arrays.asList(10L,21L)),"verified cumulative bytes");});
        System.out.println(new JSONObject().put("passed",passed).put("actualProductionJava",true).put("androidUiPackageInstallerEmulated",false).put("phoneContacted",false).toString());
    }
}
